//! `docs/SECURITY.md` cannot drift from the code (#619).
//!
//! `docs/env-vars.csv` is the registry of every `DOCLING_*` environment
//! variable the crates read: its name, a category and the source file that
//! reads it. The test holds four things together:
//!
//! 1. every `"DOCLING_…"` literal in a crate's `src/` is in the registry — a
//!    new variable has to be categorized when it is added;
//! 2. every registry row is still read where it says (no stale rows);
//! 3. every `limit`, `subprocess`, `secret` and `network` variable is named
//!    in `docs/SECURITY.md` — the categories an operator hardening a
//!    deployment must know about;
//! 4. every `DOCLING_…` name `SECURITY.md` mentions still exists in the code.
//!
//! The categories are a judgement made once per variable in the CSV:
//! `model path`, `operational`, `performance` and `debug` variables are
//! documented in README / docs/DEPLOYMENT.md rather than here.
use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};

/// The registry categories `SECURITY.md` must cover.
const SECURITY_CATEGORIES: &[&str] = &["limit", "subprocess", "secret", "network"];

/// All categories a registry row may carry.
const CATEGORIES: &[&str] = &[
    "limit",
    "subprocess",
    "secret",
    "network",
    "model path",
    "operational",
    "performance",
    "debug",
];

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

/// Every `.rs` file under each crate's `src/` (tests, examples and benches
/// are left out: the variables they set are not ones the product reads).
fn source_files() -> Vec<PathBuf> {
    fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
        let Ok(entries) = fs::read_dir(dir) else {
            return;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                walk(&path, out);
            } else if path.extension().is_some_and(|e| e == "rs") {
                out.push(path);
            }
        }
    }
    let mut out = Vec::new();
    for krate in fs::read_dir(root().join("crates")).unwrap().flatten() {
        walk(&krate.path().join("src"), &mut out);
    }
    out.sort();
    out
}

/// The `DOCLING_…` names quoted as string literals in `text`.
fn quoted_names(text: &str) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    for (i, _) in text.match_indices("\"DOCLING_") {
        let rest = &text[i + 1..];
        let end = rest
            .find(|c: char| !(c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_'))
            .unwrap_or(rest.len());
        if rest[end..].starts_with('"') {
            names.insert(rest[..end].to_string());
        }
    }
    names
}

/// The `DOCLING_…` names mentioned anywhere in `text` (prose, tables, code).
fn mentioned_names(text: &str) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    for (i, _) in text.match_indices("DOCLING_") {
        let rest = &text[i..];
        let end = rest
            .find(|c: char| !(c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_'))
            .unwrap_or(rest.len());
        let name = rest[..end].trim_end_matches('_');
        // `DOCLING_*` / `DOCLING_RS_ZIP_MAX_*` are families, not names.
        if name.len() > "DOCLING_".len() && !rest[end..].starts_with('*') {
            names.insert(name.to_string());
        }
    }
    names
}

struct Row {
    name: String,
    category: String,
    source: String,
}

fn registry() -> Vec<Row> {
    let csv = fs::read_to_string(root().join("docs/env-vars.csv")).expect("docs/env-vars.csv");
    let mut lines = csv.lines();
    assert_eq!(lines.next(), Some("name,category,source"), "CSV header");
    lines
        .filter(|l| !l.trim().is_empty())
        .map(|l| {
            let cols: Vec<&str> = l.split(',').collect();
            assert_eq!(cols.len(), 3, "registry row {l:?}: name,category,source");
            assert!(
                CATEGORIES.contains(&cols[1]),
                "registry row {l:?}: unknown category (one of {CATEGORIES:?})"
            );
            Row {
                name: cols[0].to_string(),
                category: cols[1].to_string(),
                source: cols[2].to_string(),
            }
        })
        .collect()
}

#[test]
fn every_variable_the_code_reads_is_registered() {
    let rows = registry();
    let registered: BTreeSet<&str> = rows.iter().map(|r| r.name.as_str()).collect();
    let mut missing = Vec::new();
    for file in source_files() {
        let text = fs::read_to_string(&file).unwrap();
        for name in quoted_names(&text) {
            // `docling-core::env`'s own unit tests exercise the parser with
            // throwaway names.
            if name.starts_with("DOCLING_TEST_") || registered.contains(name.as_str()) {
                continue;
            }
            missing.push(format!("{name} ({})", file.display()));
        }
    }
    missing.sort();
    missing.dedup();
    assert!(
        missing.is_empty(),
        "add these to docs/env-vars.csv with a category (and to docs/SECURITY.md \
         if it is a limit, subprocess, secret or network variable):\n{}",
        missing.join("\n")
    );
}

#[test]
fn every_registered_variable_is_read_where_the_registry_says() {
    let mut stale = Vec::new();
    for row in registry() {
        let text = fs::read_to_string(root().join(&row.source)).unwrap_or_default();
        if !text.contains(&format!("\"{}\"", row.name)) {
            stale.push(format!("{} ({})", row.name, row.source));
        }
    }
    assert!(
        stale.is_empty(),
        "docs/env-vars.csv rows whose source no longer reads them — fix the \
         path, or drop the row (and its SECURITY.md mention):\n{}",
        stale.join("\n")
    );
}

#[test]
fn security_md_names_every_hardening_variable_and_only_real_ones() {
    let doc = fs::read_to_string(root().join("docs/SECURITY.md")).unwrap();
    let mentioned = mentioned_names(&doc);
    let rows = registry();
    let undocumented: Vec<&str> = rows
        .iter()
        .filter(|r| SECURITY_CATEGORIES.contains(&r.category.as_str()))
        .filter(|r| !mentioned.contains(&r.name))
        .map(|r| r.name.as_str())
        .collect();
    assert!(
        undocumented.is_empty(),
        "docs/SECURITY.md does not name these {SECURITY_CATEGORIES:?} variables: {undocumented:?}"
    );
    let known: BTreeSet<&str> = rows.iter().map(|r| r.name.as_str()).collect();
    let unknown: Vec<&String> = mentioned
        .iter()
        .filter(|n| !known.contains(n.as_str()))
        .collect();
    assert!(
        unknown.is_empty(),
        "docs/SECURITY.md names variables the code does not read: {unknown:?}"
    );
}

//! #666: with the orientation switch on and the classifier missing, the
//! picture OCR warns once and keeps the oriented crop and the 90° turn —
//! the skewed line still reads, nothing fails. Its own test binary: it
//! points `DOCLING_OCR_TEXTLINE_ORI_ONNX` at nothing for the whole process.

use std::path::{Path, PathBuf};

use docling::Pipeline;

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

#[test]
fn a_missing_classifier_keeps_the_crop_and_the_turn() {
    let models = repo_root().join(".models");
    let rec = models.join("ocr_rec_v6.onnx").exists() || models.join("ocr_rec_en.onnx").exists();
    if !(rec && models.join("ocr_det.onnx").exists())
        || std::env::set_current_dir(repo_root()).is_err()
    {
        eprintln!("skipping: OCR models not found");
        return;
    }
    // SAFETY: the only test in this binary, set before any thread starts.
    unsafe {
        std::env::set_var(
            "DOCLING_OCR_TEXTLINE_ORI_ONNX",
            "/nonexistent/textline_ori.onnx",
        )
    };
    let bytes = std::fs::read(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/textline/skewed.png"),
    )
    .expect("fixture");
    let mut p = Pipeline::new()
        .expect("pipeline")
        .no_ocr(true)
        .no_table_former(true)
        .ocr_textline_orientation(true);
    let img = p.decode_picture(&bytes).expect("decode");
    let text = p.ocr_picture(&img).expect("no failure").expect("text").text;
    let line = "Shipping address confirmed";
    assert_eq!(text, format!("{line}\n{line}"));
}

//! The MCP catalog metadata (#669) holds together: `server.json` (the
//! official registry), the PyPI launcher it lists, the image label the
//! registry checks, the MCP bundle Smithery lists (`crates/docling-py/mcp/mcpb`,
//! named by `smithery.yaml`), `glama.json` and the root `Dockerfile` (the
//! launcher image) name the same server, stay inside the
//! catalogs' limits, and pass only flags the server takes. A
//! mismatch fails a catalog submission at release time, far from the change
//! that caused it.

use std::collections::BTreeSet;
use std::io::{BufRead, BufReader, Write};
use std::path::PathBuf;
use std::process::{Command, Stdio};

use serde_json::{json, Value};

const NAME: &str = "io.github.docling-project/docling-rs";

fn repo() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn read(rel: &str) -> String {
    std::fs::read_to_string(repo().join(rel)).unwrap_or_else(|e| panic!("{rel}: {e}"))
}

fn server() -> Value {
    serde_json::from_str(&read("server.json")).expect("server.json parses")
}

#[test]
fn server_json_is_within_the_registry_limits() {
    let s = server();
    assert_eq!(s["name"], NAME);
    // The schema's caps (2025-12-11): description and title ≤ 100.
    for key in ["description", "title"] {
        let v = s[key].as_str().unwrap();
        assert!(!v.is_empty() && v.chars().count() <= 100, "{key}: {v}");
    }
    let packages = s["packages"].as_array().unwrap();
    let pypi = packages
        .iter()
        .find(|p| p["registryType"] == "pypi")
        .unwrap();
    assert_eq!(pypi["identifier"], "docling-rs-mcp");
    assert_eq!(pypi["runtimeHint"], "uvx");
    let oci = packages
        .iter()
        .find(|p| p["registryType"] == "oci")
        .unwrap();
    assert!(oci["identifier"]
        .as_str()
        .unwrap()
        .starts_with("ghcr.io/docling-project/docling-rs:"));
}

/// The registry accepts a PyPI package whose README (its PyPI description)
/// carries `mcp-name: <name>` followed by whitespace or the comment's end,
/// and an image labelled with the name.
#[test]
fn the_listed_packages_carry_the_ownership_markers() {
    let readme = read("crates/docling-py/mcp/README.md");
    let marker = format!("mcp-name: {NAME}");
    let at = readme
        .find(&marker)
        .expect("launcher README carries the marker");
    let next = readme[at + marker.len()..].chars().next();
    assert!(matches!(next, Some(' ' | '\n' | '-')), "{next:?}");
    let pyproject = read("crates/docling-py/mcp/pyproject.toml");
    assert!(pyproject.contains("name = \"docling-rs-mcp\""));
    assert!(pyproject.contains("docling-rs-mcp = \"docling_rs_mcp:main\""));
    assert!(pyproject.contains("\"docling-rs=="));
    let dockerfile = read("crates/docling-serve/Dockerfile");
    let label = format!("LABEL io.modelcontextprotocol.server.name=\"{NAME}\"");
    for stage in [
        "FROM runtime AS cli\n",
        "FROM runtime AS cli-s390x\n",
        "FROM runtime-cuda AS cli-cuda\n",
    ] {
        let at = dockerfile
            .find(stage)
            .unwrap_or_else(|| panic!("{stage:?}"))
            + stage.len();
        let end = dockerfile[at..]
            .find("\nFROM ")
            .map_or(dockerfile.len(), |e| at + e);
        assert!(
            dockerfile[at..end].contains(&label),
            "{stage:?} lacks the label"
        );
    }
    // The launcher image at the root is the same server.
    assert!(
        read("Dockerfile").contains(&label),
        "root Dockerfile lacks the label"
    );
}

fn manifest() -> Value {
    serde_json::from_str(&read("crates/docling-py/mcp/mcpb/manifest.json"))
        .expect("manifest.json parses")
}

fn server_help() -> String {
    let out = Command::new(env!("CARGO_BIN_EXE_docling-rs"))
        .args(["mcp", "--help"])
        .output()
        .unwrap();
    assert!(out.status.success());
    String::from_utf8_lossy(&out.stdout).into_owned()
}

/// Every flag the catalogs pass is one the server takes.
#[test]
fn catalog_arguments_are_server_flags() {
    let help = server_help();
    let s = server();
    for p in s["packages"].as_array().unwrap() {
        for arg in p["packageArguments"].as_array().into_iter().flatten() {
            if let Some(flag) = arg["name"].as_str() {
                assert!(help.contains(flag), "server.json passes {flag}");
            }
        }
    }
    let m = manifest();
    for arg in m["server"]["mcp_config"]["args"].as_array().unwrap() {
        let arg = arg.as_str().unwrap();
        if arg.starts_with("--") {
            let flag = arg.split_once('=').map_or(arg, |(flag, _)| flag);
            assert!(help.contains(flag), "the bundle passes {flag}");
        }
    }
    let glama: Value = serde_json::from_str(&read("glama.json")).unwrap();
    assert!(!glama["maintainers"].as_array().unwrap().is_empty());

    // The root Dockerfile installs the launcher and runs it over stdio with
    // the server's own flags (Glama probes the built image for its tools).
    let dockerfile = read("Dockerfile");
    assert!(
        dockerfile.contains("pip install --no-cache-dir \"docling-rs-mcp$"),
        "the root Dockerfile installs the launcher"
    );
    let cmd = dockerfile
        .lines()
        .find_map(|l| l.strip_prefix("CMD "))
        .expect("the root Dockerfile has a CMD");
    let cmd: Vec<String> = serde_json::from_str(cmd).expect("CMD is the exec form");
    assert_eq!(cmd[0], "docling-rs-mcp");
    for arg in cmd.iter().filter(|a| a.starts_with("--")) {
        let flag = arg.split_once('=').map_or(arg.as_str(), |(flag, _)| flag);
        assert!(help.contains(flag), "the root Dockerfile passes {flag}");
    }
    assert!(
        !cmd.iter().any(|a| a == "--http"),
        "the catalogs probe stdio"
    );
}

/// The bundle as Smithery's CLI (4.x) reads it: `smithery.yaml` names a
/// server id its rule accepts, the runtime is one it detects (`python` —
/// MCPB's newer `uv` type is rejected), the command runs the launcher at
/// the bundle's own version (mcp-registry.yml rewrites both together), and
/// every `${user_config.*}` the command uses is a declared setting. Smithery
/// substitutes only settings that have a value, after filling defaults, so
/// an optional setting without a default would reach the server as the
/// literal `${user_config.…}`.
#[test]
fn the_mcp_bundle_runs_the_launcher() {
    let m = manifest();
    let id = read("smithery.yaml")
        .lines()
        .find_map(|l| l.strip_prefix("name: "))
        .expect("smithery.yaml names the server")
        .trim()
        .to_string();
    assert_eq!(m["name"], id.as_str());
    let mut chars = id.chars();
    assert!(
        (3..=39).contains(&id.len())
            && chars.next().is_some_and(|c| c.is_ascii_alphabetic())
            && chars.all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_'),
        "Smithery rejects the server id {id:?}"
    );
    assert_eq!(m["server"]["type"], "python");
    let config = &m["server"]["mcp_config"];
    assert_eq!(config["command"], "uvx");
    let args: Vec<&str> = config["args"]
        .as_array()
        .unwrap()
        .iter()
        .map(|a| a.as_str().unwrap())
        .collect();
    assert_eq!(
        args[0],
        format!("docling-rs-mcp@{}", m["version"].as_str().unwrap())
    );
    let mut used = BTreeSet::new();
    let env = config["env"].as_object().into_iter().flatten();
    for text in args
        .iter()
        .copied()
        .chain(env.map(|(_, v)| v.as_str().unwrap()))
    {
        let mut rest = text;
        while let Some(at) = rest.find("${user_config.") {
            let key = &rest[at + "${user_config.".len()..];
            let end = key.find('}').expect("closed placeholder");
            used.insert(key[..end].to_string());
            rest = &key[end..];
        }
    }
    let settings = m["user_config"].as_object().unwrap();
    let declared: BTreeSet<String> = settings.keys().cloned().collect();
    assert_eq!(used, declared, "settings used vs. declared");
    for (key, setting) in settings {
        assert!(
            setting["required"] == true || setting.get("default").is_some(),
            "{key}: optional without a default"
        );
    }
    let icon = std::fs::read(
        repo()
            .join("crates/docling-py/mcp/mcpb")
            .join(m["icon"].as_str().unwrap()),
    )
    .expect("the bundle's icon");
    assert!(icon.starts_with(b"\x89PNG"), "MCPB icons are PNG");
}

/// The tools the bundle advertises (Smithery's listing shows them) are the
/// ones the server lists.
#[test]
fn the_mcp_bundle_lists_the_server_tools() {
    let mut child = Command::new(env!("CARGO_BIN_EXE_docling-rs"))
        .args(["mcp", "--root"])
        .arg(repo())
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    let mut stdin = child.stdin.take().unwrap();
    let mut stdout = BufReader::new(child.stdout.take().unwrap());
    for message in [
        json!({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {
            "protocolVersion": "2025-06-18", "capabilities": {},
            "clientInfo": {"name": "mcp-registry-test", "version": "0"}}}),
        json!({"jsonrpc": "2.0", "method": "notifications/initialized"}),
        json!({"jsonrpc": "2.0", "id": 2, "method": "tools/list", "params": {}}),
    ] {
        writeln!(stdin, "{message}").unwrap();
    }
    stdin.flush().unwrap();
    let listed: BTreeSet<String> = loop {
        let mut line = String::new();
        assert!(
            stdout.read_line(&mut line).unwrap() > 0,
            "server closed stdout"
        );
        let message: Value = serde_json::from_str(&line).unwrap();
        if message["id"] == 2 {
            break message["result"]["tools"]
                .as_array()
                .unwrap()
                .iter()
                .map(|t| t["name"].as_str().unwrap().to_string())
                .collect();
        }
    };
    drop(stdin);
    let _ = child.kill();
    let _ = child.wait();
    let advertised: BTreeSet<String> = manifest()["tools"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| t["name"].as_str().unwrap().to_string())
        .collect();
    assert_eq!(advertised, listed);
}

//! `docling-rs mcp` (#669) end to end: the real binary, spoken to the way an
//! MCP client does — newline-delimited JSON-RPC on stdio, and Streamable HTTP
//! for `--http`. Only declarative fixtures, so no models are needed.
#![cfg(feature = "mcp")]

use std::io::{BufRead, BufReader, Read, Write};
use std::net::TcpStream;
use std::path::PathBuf;
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};

use serde_json::{json, Value};

fn fixtures() -> PathBuf {
    std::fs::canonicalize(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/data"))
        .unwrap()
}

/// A stdio session: the child plus its two pipe ends.
struct Session {
    child: Child,
    stdin: ChildStdin,
    stdout: BufReader<ChildStdout>,
    next_id: u64,
}

impl Session {
    /// Start `docling-rs mcp ARGS…` and complete the initialize handshake.
    fn start(args: &[&str]) -> (Self, Value) {
        let mut child = Command::new(env!("CARGO_BIN_EXE_docling-rs"))
            .arg("mcp")
            .args(args)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()
            .expect("spawn docling-rs mcp");
        let stdin = child.stdin.take().unwrap();
        let stdout = BufReader::new(child.stdout.take().unwrap());
        let mut session = Self {
            child,
            stdin,
            stdout,
            next_id: 0,
        };
        let init = session.request(
            "initialize",
            json!({
                "protocolVersion": "2025-06-18",
                "capabilities": {},
                "clientInfo": {"name": "docling-cli-test", "version": "0"}
            }),
        );
        session.send(&json!({"jsonrpc": "2.0", "method": "notifications/initialized"}));
        (session, init)
    }

    fn send(&mut self, message: &Value) {
        writeln!(self.stdin, "{message}").unwrap();
        self.stdin.flush().unwrap();
    }

    /// Send a request and return its `result` (notifications in between are
    /// skipped).
    fn request(&mut self, method: &str, params: Value) -> Value {
        self.next_id += 1;
        let id = self.next_id;
        self.send(&json!({"jsonrpc": "2.0", "id": id, "method": method, "params": params}));
        loop {
            let mut line = String::new();
            assert!(
                self.stdout.read_line(&mut line).unwrap() > 0,
                "server closed stdout"
            );
            let message: Value = serde_json::from_str(&line)
                .unwrap_or_else(|e| panic!("stdout carried a non-JSON-RPC line ({e}): {line:?}"));
            if message["id"] == json!(id) {
                assert!(message.get("error").is_none(), "{method}: {message}");
                return message["result"].clone();
            }
        }
    }

    /// `tools/call` → (text, isError).
    fn call(&mut self, tool: &str, arguments: Value) -> (String, bool) {
        let result = self.request("tools/call", json!({"name": tool, "arguments": arguments}));
        let text = result["content"][0]["text"]
            .as_str()
            .unwrap_or_default()
            .to_string();
        (text, result["isError"] == json!(true))
    }
}

impl Drop for Session {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

#[test]
fn stdio_lists_the_three_tools() {
    let root = fixtures();
    let (mut s, init) = Session::start(&["--root", root.to_str().unwrap()]);
    assert_eq!(init["serverInfo"]["name"], "docling-rs");
    assert!(init["capabilities"]["tools"].is_object(), "{init}");
    let tools = s.request("tools/list", json!({}));
    let mut names: Vec<&str> = tools["tools"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| t["name"].as_str().unwrap())
        .collect();
    names.sort_unstable();
    assert_eq!(
        names,
        ["convert", "convert_to_markdown", "list_input_formats"]
    );
    // MarkItDown's contract: one required string argument named `uri`.
    let tool = tools["tools"]
        .as_array()
        .unwrap()
        .iter()
        .find(|t| t["name"] == "convert_to_markdown")
        .unwrap();
    assert_eq!(tool["inputSchema"]["required"], json!(["uri"]));
    assert_eq!(tool["inputSchema"]["properties"]["uri"]["type"], "string");
    assert_eq!(tool["annotations"]["readOnlyHint"], true);
}

#[test]
fn stdio_converts_a_docx_fixture() {
    let root = fixtures();
    let (mut s, _) = Session::start(&["--root", root.to_str().unwrap()]);
    // A path relative to the root…
    let (md, is_error) = s.call(
        "convert_to_markdown",
        json!({"uri": "docx/sources/lorem_ipsum.docx"}),
    );
    assert!(!is_error, "{md}");
    assert!(md.contains("Lorem ipsum dolor sit amet"), "{md}");
    // …a file: URI…
    let uri = format!(
        "file://{}",
        root.join("docx/sources/lorem_ipsum.docx").display()
    );
    let (md2, is_error) = s.call("convert_to_markdown", json!({"uri": uri}));
    assert!(!is_error, "{md2}");
    assert_eq!(md, md2);
    // …a data: URI, and `convert` with another output format.
    let (md, is_error) = s.call(
        "convert_to_markdown",
        json!({"uri": "data:text/html;base64,PGgxPkhlbGxvPC9oMT48cD5Xb3JsZDwvcD4="}),
    );
    assert!(!is_error, "{md}");
    assert_eq!(md.trim(), "# Hello\n\nWorld");
    let (json_out, is_error) = s.call(
        "convert",
        json!({"uri": "docx/sources/lorem_ipsum.docx", "to": "json"}),
    );
    assert!(!is_error, "{json_out}");
    let doc: Value = serde_json::from_str(&json_out).unwrap();
    assert_eq!(doc["schema_name"], "DoclingDocument");
}

#[test]
fn stdio_refuses_what_the_operator_did_not_allow() {
    let root = fixtures().join("md");
    let (mut s, _) = Session::start(&["--root", root.to_str().unwrap()]);
    for uri in [
        "../docx/sources/lorem_ipsum.docx",
        "/etc/passwd",
        "file:///etc/passwd",
    ] {
        let (text, is_error) = s.call("convert_to_markdown", json!({"uri": uri}));
        assert!(is_error, "{uri}: {text}");
        assert!(text.contains("outside the server's root"), "{uri}: {text}");
    }
    let (text, is_error) = s.call(
        "convert_to_markdown",
        json!({"uri": "https://example.com/report.pdf"}),
    );
    assert!(is_error && text.contains("--allow-url-fetch"), "{text}");
    let (text, is_error) = s.call(
        "convert",
        json!({"uri": "x.md", "options": {"not_an_option": 1}}),
    );
    assert!(is_error && text.contains("unknown field"), "{text}");
    // A form's text values read as the option's type (MCP Inspector sends
    // `"true"`); a value no reading accepts names the option.
    let (text, is_error) = s.call(
        "convert",
        json!({"uri": "sources/duck.md", "options": {"strict": "true", "compact_tables": "1"}}),
    );
    assert!(!is_error, "{text}");
    let (text, is_error) = s.call(
        "convert",
        json!({"uri": "sources/duck.md", "options": {"strict": "maybe"}}),
    );
    assert!(is_error && text.contains("strict: cannot read"), "{text}");
    // A tool error leaves the session usable.
    let (formats, is_error) = s.call("list_input_formats", json!({}));
    assert!(
        !is_error && formats.lines().any(|l| l == "docx"),
        "{formats}"
    );
}

#[test]
fn http_refuses_a_public_bind_without_allow_remote() {
    let out = Command::new(env!("CARGO_BIN_EXE_docling-rs"))
        .args(["mcp", "--http", "--host", "0.0.0.0", "--port", "0"])
        .output()
        .unwrap();
    assert!(!out.status.success());
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("--allow-remote"), "{stderr}");
    // An HTTP flag on a stdio launch is a usage error, not silently ignored.
    let out = Command::new(env!("CARGO_BIN_EXE_docling-rs"))
        .args(["mcp", "--bearer-token", "x"])
        .stdin(Stdio::null())
        .output()
        .unwrap();
    assert_eq!(out.status.code(), Some(2));
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("applies to --http only"), "{stderr}");
}

/// One HTTP/1.1 POST; the status code and the body.
fn post(port: u16, headers: &[(&str, &str)], body: &Value) -> (u16, String) {
    let body = body.to_string();
    let mut stream = TcpStream::connect(("127.0.0.1", port)).unwrap();
    let mut request = format!(
        "POST /mcp HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nContent-Type: application/json\r\n\
         Accept: application/json, text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n",
        body.len()
    );
    for (k, v) in headers {
        request.push_str(&format!("{k}: {v}\r\n"));
    }
    request.push_str("\r\n");
    request.push_str(&body);
    stream.write_all(request.as_bytes()).unwrap();
    let mut response = String::new();
    stream.read_to_string(&mut response).unwrap();
    let status = response
        .split_whitespace()
        .nth(1)
        .and_then(|s| s.parse().ok())
        .unwrap_or(0);
    (status, response)
}

#[test]
fn http_serves_with_a_bearer_token() {
    let root = fixtures();
    let mut child = Command::new(env!("CARGO_BIN_EXE_docling-rs"))
        .args(["mcp", "--http", "--port", "0", "--bearer-token", "t0ken"])
        .args(["--root", root.to_str().unwrap()])
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    // The startup line names the bound address (`--port 0` picks one).
    let mut line = String::new();
    BufReader::new(child.stderr.take().unwrap())
        .read_line(&mut line)
        .unwrap();
    let port: u16 = line
        .split("http://127.0.0.1:")
        .nth(1)
        .and_then(|rest| rest.split('/').next())
        .and_then(|p| p.parse().ok())
        .unwrap_or_else(|| panic!("no address in {line:?}"));
    let init = json!({
        "jsonrpc": "2.0", "id": 1, "method": "initialize",
        "params": {"protocolVersion": "2025-06-18", "capabilities": {},
                   "clientInfo": {"name": "t", "version": "0"}}
    });
    let (status, _) = post(port, &[], &init);
    assert_eq!(status, 401);
    let (status, _) = post(port, &[("Authorization", "Bearer wrong")], &init);
    assert_eq!(status, 401);
    // A web page's Origin is refused on a loopback bind (DNS rebinding /
    // drive-by requests from the user's browser).
    let (status, _) = post(
        port,
        &[
            ("Authorization", "Bearer t0ken"),
            ("Origin", "https://evil.example"),
        ],
        &init,
    );
    assert_eq!(status, 403);
    let (status, body) = post(port, &[("Authorization", "Bearer t0ken")], &init);
    assert_eq!(status, 200, "{body}");
    assert!(body.contains("\"name\":\"docling-rs\""), "{body}");
    let _ = child.kill();
    let _ = child.wait();
}

/// Started in `/` (where desktop clients often start servers) without
/// `--root`, the server refuses rather than open the whole file system; an
/// explicit `--root /` is the operator's choice and starts.
#[cfg(unix)]
#[test]
fn a_defaulted_file_system_root_is_refused() {
    let out = Command::new(env!("CARGO_BIN_EXE_docling-rs"))
        .arg("mcp")
        .current_dir("/")
        .stdin(Stdio::null())
        .output()
        .unwrap();
    assert_eq!(out.status.code(), Some(2));
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stderr.contains("file system root"), "{stderr}");
    let out = Command::new(env!("CARGO_BIN_EXE_docling-rs"))
        .args(["mcp", "--root=/"])
        .current_dir("/")
        .stdin(Stdio::null())
        .output()
        .unwrap();
    // stdin closed at once: the server starts, sees no client and exits.
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!stderr.contains("file system root"), "{stderr}");
    assert!(stderr.contains("root /"), "{stderr}");
}

//! REST API integration test, fully offline: memory store + hashing embedder,
//! server bound to an ephemeral port, exercised with a real HTTP client.

use docling_rag::config::{DbBackend, EmbedProvider, SourceKind};
use docling_rag::{api, Pipeline, RagConfig};

async fn spawn_server() -> (String, reqwest::Client) {
    let dir = std::env::temp_dir().join(format!(
        "rag-api-{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0)
    ));
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(
        dir.join("vectors.md"),
        "# Vector Search\n\nA vector database stores embeddings so that semantic \
         search can find passages by meaning rather than exact keywords.",
    )
    .unwrap();
    std::fs::write(
        dir.join("smoothie.md"),
        "# Smoothie\n\nBlend a banana with yogurt and honey for a quick breakfast smoothie.",
    )
    .unwrap();

    let cfg = RagConfig {
        db_backend: DbBackend::Memory,
        embed_provider: EmbedProvider::Hash,
        embed_dim: 256,
        source: SourceKind::Folder,
        source_path: dir.display().to_string(),
        ..RagConfig::default()
    };
    let pipeline = Pipeline::from_config(&cfg).await.unwrap();
    pipeline.ingest_all().await.unwrap();

    let app = api::router(pipeline, vec!["test-key".into(), "other-key".into()]).unwrap();
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });
    (format!("http://{addr}"), reqwest::Client::new())
}

#[tokio::test]
async fn rest_api_end_to_end() {
    let (base, client) = spawn_server().await;

    // /health is public, and tells the UI whether answers are possible.
    let r = client.get(format!("{base}/health")).send().await.unwrap();
    assert_eq!(r.status(), 200);
    let h: serde_json::Value = r.json().await.unwrap();
    assert_eq!(h["status"], "ok");
    assert!(
        h["llm"].is_boolean(),
        "health reports llm availability: {h}"
    );
    assert_eq!(h["llm_model"].is_null(), !h["llm"].as_bool().unwrap());

    // Everything under /api requires a key.
    let r = client
        .get(format!("{base}/api/documents"))
        .send()
        .await
        .unwrap();
    assert_eq!(r.status(), 401);
    let r = client
        .get(format!("{base}/api/documents"))
        .header("X-Api-Key", "wrong")
        .send()
        .await
        .unwrap();
    assert_eq!(r.status(), 401);

    // X-Api-Key works; documents carry their processing metrics.
    let r = client
        .get(format!("{base}/api/documents"))
        .header("X-Api-Key", "test-key")
        .send()
        .await
        .unwrap();
    assert_eq!(r.status(), 200);
    let body: serde_json::Value = r.json().await.unwrap();
    let docs = body["documents"].as_array().unwrap();
    assert_eq!(docs.len(), 2);
    assert!(docs[0]["metadata"]["metrics"]["words"].as_u64().unwrap() > 0);

    // Bearer auth works too; single-document lookup and 404.
    let id = docs[0]["id"].as_str().unwrap();
    let r = client
        .get(format!("{base}/api/documents/{id}"))
        .header("Authorization", "Bearer other-key")
        .send()
        .await
        .unwrap();
    assert_eq!(r.status(), 200);
    let r = client
        .get(format!("{base}/api/documents/nope"))
        .header("X-Api-Key", "test-key")
        .send()
        .await
        .unwrap();
    assert_eq!(r.status(), 404);

    // Stats.
    let r = client
        .get(format!("{base}/api/stats"))
        .header("X-Api-Key", "test-key")
        .send()
        .await
        .unwrap();
    let stats: serde_json::Value = r.json().await.unwrap();
    assert_eq!(stats["documents"], 2);

    // GET search in each offline mode finds the vector-database passage.
    for mode in ["vector", "bm25", "hybrid"] {
        let r = client
            .get(format!("{base}/api/search"))
            .query(&[
                ("q", "semantic search in a vector database"),
                ("mode", mode),
                ("k", "3"),
            ])
            .header("X-Api-Key", "test-key")
            .send()
            .await
            .unwrap();
        assert_eq!(r.status(), 200, "mode {mode}");
        let body: serde_json::Value = r.json().await.unwrap();
        assert_eq!(body["mode"], mode);
        let results = body["results"].as_array().unwrap();
        assert!(!results.is_empty(), "mode {mode} returned nothing");
        assert!(
            results[0]["chunk"]["text"]
                .as_str()
                .unwrap()
                .contains("vector database"),
            "mode {mode} ranked the wrong chunk"
        );
    }

    // POST body form.
    let r = client
        .post(format!("{base}/api/search"))
        .header("X-Api-Key", "test-key")
        .json(&serde_json::json!({"query": "banana breakfast", "mode": "bm25", "top_k": 2}))
        .send()
        .await
        .unwrap();
    assert_eq!(r.status(), 200);
    let body: serde_json::Value = r.json().await.unwrap();
    assert!(body["results"][0]["chunk"]["text"]
        .as_str()
        .unwrap()
        .contains("banana"));

    // Bad inputs: unknown mode and LLM mode without a key are 400s.
    let r = client
        .get(format!("{base}/api/search"))
        .query(&[("q", "x"), ("mode", "warp-drive")])
        .header("X-Api-Key", "test-key")
        .send()
        .await
        .unwrap();
    assert_eq!(r.status(), 400);
    let r = client
        .get(format!("{base}/api/search"))
        .query(&[("q", "x"), ("mode", "hyde")])
        .header("X-Api-Key", "test-key")
        .send()
        .await
        .unwrap();
    assert_eq!(r.status(), 400);
}

